#[no_mangle]
pub unsafe extern "C" fn hamming_code(a:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if a.is_null()||n<3{return -1;}let v=std::slice::from_raw_parts(a,n);let(r,m)=(v[0],v[1]);if r<1||r>5||m<1||m>32||n!=(2+m)as usize||r+m<=((1i64<<r)-(m-1)){return -1;}if v[2..].iter().any(|&x|x!=48&&x!=49){return -1;}let total=(r+m)as usize;if total<(1usize<<((r-1)as usize)){return -1;}if out.is_null()||cap<total+1{return -2;}let mut code=[0u8;40];let mut data=0usize;for p in 1..=total{if p&(p-1)!=0||p>(1usize<<((r-1)as usize)){code[p-1]=v[2+data]as u8;data+=1;}else{code[p-1]=b'0';}}for bit in 0..r as usize{let parity=1usize<<bit;let mut value=0;for p in 1..=total{if p&parity!=0&&code[p-1]==b'1'{value^=1;}}code[parity-1]=b'0'+value;}let result=std::slice::from_raw_parts_mut(out,cap);result[..total].copy_from_slice(&code[..total]);result[total]=0;total as i64}
